const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g '!*pycache*' -g '!*.pyc' | head -100 && git status --short --branch && git remote -v",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:4000}),
  tools.exec_command({cmd:"/opt/reference/executable --help",workdir:"/tmp",yield_time_ms:10000,max_output_tokens:3000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

